from django.db import models
from register.models import *

class Transaction(models.Model):
	register=models.ForeignKey(Register, on_delete=models.CASCADE)
	tdate=models.DateTimeField(null=True, blank=True)
	level=models.CharField(max_length=5, null=True, blank=True)
	service=models.CharField(max_length=5, null=True, blank=True)
	status=models.CharField(max_length=5, null=True, blank=True)
	user=models.ForeignKey(User, on_delete=models.CASCADE, default=1)
	def __str__(self):
		return '%s %s' %(self.register, self.tdate)


